`default_nettype none

// Independently model the carry-save recombination and word selection.
// Partial products are arbitrary, including values not generated by the DSPs.
module mul_recombine_contract (
  input logic clk
);
  (* anyseq *) logic [31:0] p0, p3;
  (* anyseq *) logic [33:0] p1, p2;
  (* anyseq *) logic hi;
  logic [63:0] sum1, carry1;
  logic [31:0] result;
  roco_cpu_mul_term compressor (
      .p0(p0),
      .p1(p1),
      .p2(p2),
      .p3(p3),
      .sum1(sum1),
      .carry1(carry1)
  );
  roco_cpu_mul_sum selector (
      .sum1(sum1),
      .carry1(carry1),
      .hi(hi),
      .result(result)
  );

  logic signed [63:0] cross_a, cross_b;
  logic [63:0] expected;
  assign cross_a = 64'($signed(p1));
  assign cross_b = 64'($signed(p2));
  assign expected = 64'(p0) + ((cross_a + cross_b) << 16) + (64'(p3) << 32);
  always @(posedge clk) begin
    assert (result == (hi ? expected[63:32] : expected[31:0]));
    cover (hi && p1[33] && !p2[33] && result != 0);
    cover (!hi && !p1[33] && p2[33] && result != 0);
  end
endmodule
